// Diagnostic probe generated by ppl (safe to delete).
// Tests Programs() assignment forms: variable-empty delete, literal-empty
// delete (documented form). Marker note uses the proven variable-RHS write.
EXPORT ZZT_PROBE3()
BEGIN
  LOCAL r,e,ok;
  PRINT("P3 start");
  r:="q1-varwrite";
  Notes("ZZT_PROBER"):=r;
  PRINT("q1 ok");
  e:="";
  ok:=1;
  IFERR Programs("ZZT_POC01"):=e; THEN ok:=0; END;
  IF ok THEN r:="q2-progvardel-ok"; ELSE r:="q2-progvardel-ERR"; END;
  Notes("ZZT_PROBER"):=r;
  PRINT(r);
  ok:=1;
  IFERR Programs("ZZT_POC01"):=""; THEN ok:=0; END;
  IF ok THEN r:="q3-proglitdel-ok"; ELSE r:="q3-proglitdel-ERR"; END;
  Notes("ZZT_PROBER"):=r;
  PRINT(r);
  r:="q4-programs-done";
  Notes("ZZT_PROBER"):=r;
  PRINT("P3 done");
  RETURN 0;
END;
